contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: deposit an amount into c, then attempt withdrawAll
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        // ensure this test contract has enough Ether to deposit
        require(address(this).balance >= depositAmount, "insufficient test balance");

        // deposit into c from this contract
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // observe c's balance before withdraw and this contract's balance before withdraw
        uint cBalBefore = address(c).balance;
        uint selfBalBefore = address(this).balance;

        // attempt withdrawAll and record whether it reverted
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe balances after
        uint cBalAfter = address(c).balance;
        uint selfBalAfter = address(this).balance;

        // General rule: if withdrawAll succeeded then c's balance decreased by exactly depositAmount
        // and this contract's balance increased by exactly depositAmount
        assert(
            reverted || (cBalBefore == cBalAfter + depositAmount && selfBalAfter == selfBalBefore + depositAmount)
        );
    }

    // allow receiving Ether when c sends funds back
    receive() external payable {}
}

